/**
 * Supr UI MCP — token loading.
 *
 * Tokens are read from the REAL token source: the built output of
 * @mrtechnology/tokens (`dist/tokens.json`, generated by Style Dictionary from
 * `tokens/*.json` in W3C DTCG format). Token values are never duplicated
 * here by hand. If @mrtechnology/tokens has not been built yet, loading fails
 * with a message telling the operator how to build it.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

export type TokenTree = Record<string, unknown>;

export const TOKEN_GROUPS = [
  "color",
  "spacing",
  "radius",
  "border",
  "motion",
  "typography",
] as const;

export type TokenGroup = (typeof TOKEN_GROUPS)[number];

export const TOKEN_SOURCE =
  "@mrtechnology/tokens dist/tokens.json (Style Dictionary build of tokens/*.json, W3C DTCG)";

let cached: TokenTree | null = null;

export function loadTokens(): TokenTree {
  if (cached) return cached;
  const require = createRequire(import.meta.url);
  let resolved: string;
  try {
    resolved = require.resolve("@mrtechnology/tokens/tokens.json");
  } catch {
    throw new Error(
      "supr-mcp: @mrtechnology/tokens is not built yet — run `npm run build` in packages/tokens (or `npm run build` at the repo root), then restart this server.",
    );
  }
  cached = JSON.parse(readFileSync(resolved, "utf8")) as TokenTree;
  return cached;
}

/** Resolve a dot path such as `color.cobalt.500` against the token tree. */
export function getTokenByPath(path: string): { found: boolean; value: unknown } {
  const segments = path.split(".").filter(Boolean);
  if (segments.length === 0) return { found: false, value: undefined };
  let node: unknown = loadTokens();
  for (const segment of segments) {
    if (node === null || typeof node !== "object") return { found: false, value: undefined };
    node = (node as Record<string, unknown>)[segment];
    if (node === undefined) return { found: false, value: undefined };
  }
  return { found: true, value: node };
}
